def sieve(n):
    prime = [True for i in range(n+1)]
    p = 2
    while (p * p <= n):
        if (prime[p] == True):
            for i in range(p * p, n+1, p):
                prime[i] = False
        p += 1
    return prime

def LCM(a,b):
    a, b = abs(a), abs(b)
    return abs((a*b))/gcd(a,b)

def IsPrime(x):
    if x == 2:
        return True
    if x <= 1 or x%2==0:
        return False
    for i in range(3,int(sqrt(x))+1,2):
        if x%i==0:
            return False
    return True

def power(a,n,m):
    result = 1 
    a %= m 
    while(n > 0){
        if ((n & 1) == 1)
            result = (result * a) % m  
        n >>= 1; 
        a = (a * a) % m    
    }
    return result 

def modInverse(a,m):
    return power(a,m-2,m)

