def check_vika(n, m, s):
    # Initialize four sets
    v = set()
    i = j = k = a = []

    # Find all occurrences of "v", "i", "k", and "a" in the carpet and add them to their respective lists
    for char in s:
        if char == "v":
            if len(v) < 4 or v & {j} is None: 
                return False
            j = None
        elif char == "i":
            if len(i) < 3 or i & {k} is None: 
                return False
            k = None
        elif char == "k":
            if len(k) < 2 or k & {j} is not None and a is not None:
                return False
            j = None
        else:
            if len(a) < 1 or a & {i} is not None: 
                return False
            a = None

    # If the function hasn't returned False by now, Vika will like the carpet
    for c in range(0, n):
        if v & set(s[c:m]) is None:
            return "NO"

    # Finally, check the last column: we can select 1 through 4 distinct columns from left to right that contain "v", "i", "k," and "a" respectively
    if len(v) >= 2 or ((len(i) == 0 and k is None and a is not None):
        # Check that the values have been filled up in the last columns first, so we won't be able to read them all later.
        return ("Yes" if (a and i and j and k else False))
    elif len(v) >= 1 or a is None:
        return ("Yes")
    elif j is not None: 
        # Check when there are at least two columns filled in the last columns, that we can read them.
        return "NO"
    elif k is not None: 
        # When only one column is left for Vika to read, check if there's a column after it that includes an element from j (which contains v), i or k. In this situation, we can't read the names yet, but these elements won't be in those columns later when we read them with "v", "i" and "k".
        return "NO"
    else: 
        # When there's only one column left for Vika to read, check it then.
        return ("Yes")

