import heapq
from typing import List

def find_minimum_operations(s: str) -> int:
    n = len(s)

    if n == 4 and s.count('0') <= 1:
        return -1
    elif any(s.count(str(i)) > 1 for i in range(10)):
        return -1
    else:
        dp = [[float('inf'), float('inf')] for _ in range(n)]
        dp[0][0] = 1
        queue = [(1, 3 * (n + 7)), [(0, s[0])]]
        while queue:
            l, r = heapq.heappop(queue)
            if dp[l][0] != 5 and l > 0:
                heapq.heappush(queue, (l - 1, r))
            if dp[r][0] != 5 and r < n - 1:
                heapq.heappush(queue, (r + 2, l))
            for j in range(4):
                i = int(s[j])
                l, r = s[j], l + 1
                while l <= r:
                    m = (l + r) // 2
                    if dp[m][0] != -1 and ((m - 2) * (i << 3) >= dp[l][0]) and ((m - 2) * i << 3 + m) > r:
                        l = m + 1
                else:
                    dp[l][j] = min(dp[m if m == j else r][j], m * 4)
        return dp[-1][-1]

