class SegmentTree:
    def __init__(self, n):
        self.seg_tree = [0] * (4*n)
        self.n = n

    def update(self, idx, val):
        if idx < 1 or idx > self.n:
            raise Exception("Segment Tree is out of bounds")
        index = idx
        while not index%2:
            index >>= 1
        left_idx, right_idx = [index]*4, [index] * 4 
        while left_idx != right_idx:    
           if left_idx > right_idx:
              self.seg_tree[index] = val
              left_idx >>= 1            
           else:
              right_idx >>= 1
              self.seg_tree[index] = min(self.seg_tree[left_idx],self.seg_tree[right_idx])

    def query_sum(self, idx):

        def inner(left, mid, right):
            if left==right:
                return self.seg_tree[idx]
            s = bisect_right(left, mid)
            p_l = (mid+1+s-2)//(s+1) * (self.seg_tree[mid] - self.seg_tree[left-1]) + (s-1)*(self.seg_tree[s]- self.seg_tree[left])
            p_r = s*(self.seg_tree[mid+1]-(self.seg_tree[right]+1)) 
            return sum(self.seg_tree[p_l:p_r])

        while True:
            mid = (left + right)//2
            if mid >= len(left):
                left, right = [], []
            elif mid <= mid+63//64:    # 3*sqrt(n)
                left, right = inner(list(bisect_left(left, idx)), mid, min(bisect_right(left, idx+1),right))
                break

        return inner(left,mid,right)

