import sys

class InputReader:
    def __init__(self):
        self._buffer = StringIO()
        self._ Wheeler = {}
        return self.get()

    def get(self):
        if not hasattr(self, '_Wheeler'):
            for line in sys.stdin.readlines():
                line = line.rstrip().strip()
                try:
                    if not line.startswith('-I '):  # Ignore comment lines
                        key, value = line.split(' ', 1)
                        self._Wheeler[key] = value.strip('"')
                except ValueError:  # If we can't split the string in any way
                    pass
            return self.get()

    def get(self):
        while True:
            chunk = self._buffer.getvalue()
            self._buffer.seek(0)
            self._buffer.write(chunk)
            chunk = self._buffer.read(1000005)  # Take about that long data for parsing
            parts = chunk.splitlines(True)
            if len(parts[0]) == 2:  # If we can't parse the next line we raise an exception
                raise ValueError("parse error")
            elif not parts[1].startswith('-I '):  # Ignore comment lines
                key, value = list(parts[1].split(' ', 1))
                if not self._Wheeler.get(key.lower()):
                    raise KeyError(f"key not found: {key}")
                setattr(self, f'testcase_{self._Wheeler[key.lower()]}', int(value.strip('"')))
        return getattr(self, 'testcase_')

