class Solution {
    public double maxSum(int[] nums) {

        int N = nums.length;
        for (int mask = ((1 << N) - 1); ~mask; mask &= mask - 1 );
        long left = 0, right = Long.MAX_VALUE;

        for (int i =0 ; i <  N; ++i){
            int sum = 0, mask2 = 0;
            for (int bit : (1<<N) ) {
                if ((bit & mask) == 0) continue;
                sum += nums[i];
                mask2 += bit;
            }
            long resLeft = solve(left,sum);
            long resRight = solve(right -sum+nums[i], -sum);
            left = Math.min(resLeft, left);
            right = Math.max(resRight, right);

        }

        return calculate(right ,N);
    }

     public  double solve(int sum,int count){
       if (count ==0)  {
           return Math.abs(sum);
       }
       int mid = (int)(sum/count);

       boolean check1 = true;
       while(check1){
           check1 = false;
           for (int i=0 ; i < count; ++i ){
               sum-=mid+1;
               -count- i <= 1 ?  check1=true:false ;
            }
       }

        return calculate(sum,count);

     }

     public long solve2(int mid){
       int L =N;
       int R;
       while (L <R){

           int M = (L + R) >> 1;

           if(solve(maxSum(nums),M)<=maxSum(nums)-solve(minSum(nums,M))){
               R = M;
           }else {
               L = M+1;
           }

       }
       return solve2(L);

     }

     public long minSum(int[] nums){
        int len =nums.length;
        long sum = 0;

        for (int i=0 ; i <len; ++i){
            sum += nums[i];
        }
         if (!nums.isEmpty() && Math.abs(sum) == 0) return 0;
        return sum;
     }

