    import math
    from functools import reduce
    def binary_search(low, high, func):
        if low >= high:
            return None
        mid = (low + high) // 2
        return func(mid) if func(mid) else binary_search(low, mid - 1, func)
    # Calculate the sum of all numbers in rows from 1 to M.
    total_sum_M = reduce(lambda x, y: x * (y + 1), range(1, M + 2))

    # Calculate the sum of all numbers in columns from M+1 to N.
    total_sum_N = reduce(lambda x, y: x + y * (M + 1), range(M + 1, N + 1))

    # The number of distinct tight dominoes is given by
    # total_sum_M - lower bound of total_sum_M that has the same column as elements in
    # [total_sum_M - i * j, total_sum_N] where i and j are between 0 and M+1.
    total_tight = sum(
        math.factorial(M + n) 
        for n in range(2, min(N + 1, M + 2))
        if ((M + n) % 2 == 0)
    )

