class Solution:
    def ruffleSort(self, a):
        n = len(a)
        for i in range(n):
            j = int(math.random*((n-1)*i))
            a[i], a[j] = a[j], a[i]
        return sorted(a)

    def totalOrder(self, a):
        ans = defaultdict(int)
        for s in a:
            ans[s[0]] += 2
            ans[s[1]] += 2
            ans[s[2]] += 1

        m = max(ans.values())
        return [ans[x] - m for x in sorted(ans)]

