from typing import List

def solve(n: int, k: int, p: List[int]) -> int:
    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + p[i - 1]

    low, high = 2 if k == 1 else k, min(p.count(i) for i in range(k))

    while low <= high:
        mid = (low + high) // 2
        total = prefix_sum[k] - sum([prefix_sum[i] for i in range(1, mid))]

        for i in range(mid):
            if prefix_sum[mid] == prefix_sum[i]:
                break

        else:
            low = mid + 1

        while low <= high and total > prefix_sum[mid]:
            hi = high
            for i in range(k, mid - 1, -1):
                j = mid - length if len(p) >= mid + 1 else mid
                if p[i] == p[j]:
                    break
                elif p[i] < p[j]: 
                    left_sum_1 = prefix_sum[p[i - 1]:i]
                    right_sum_1 = prefix_sum[i:j]  
                    length = i - p[i - 1]

                    total += j - mid + 1 - (left_sum_1 + right_sum_1 // length)

            low = hi
    return high

