def get_primes(n):
    primes = []
    if n > 1:
        for i in range(2, int(n**0.5) + 1):
            if not (n % i == 0):
                primes.append(i)
            while n % i == 0:
                n //= i
        if n > 1:  # If n is a prime number itself
            primes.append(n)
    return primes

def get_primes_list(n):
    primes = set()
    for m in range(2, int((n ** (1 / 2)) + 0.5)):
        k = 2 * m
        while True:
            if all(m % p > 0 for p in primes):
                break
            primes.add(k)
            k += m
    return sorted(list(primes))

def get_bit_count(n):
    count = 0
    while n:
        n, bit = divmod(n, 2)
        count += bit
    return count

