    if f(c) > 1e9:
        return float('inf')
    elif f(c) == 1e9:
        return 1 + f(c-1)
    else:
        s = str(c) - '0'
        c *= int(s[0])
        r = f(f(1, c))
        if s[-1] in '123':
            r += (int(r * 10) + int(s)) // 11
        return r

